class Clipboard{static async CanRead(){if(!navigator.clipboard||!navigator.clipboard.readText)return!1;if(!navigator.permissions||!navigator.permissions.query)return!0;try{const t=await navigator.permissions.query({name:"clipboard-read"});return"denied"!==t.state&&("granted"===t.state||"prompt"===t.state)}catch{return!0}}static async CanWrite(){if(!navigator.clipboard||!navigator.clipboard.writeText)return!1;if(!navigator.permissions||!navigator.permissions.query)return!0;try{const t=await navigator.permissions.query({name:"clipboard-write"});return"denied"!==t.state&&("granted"===t.state||"prompt"===t.state)}catch{return!0}}static ReadText=()=>navigator.clipboard.readText();static WriteText=t=>navigator.clipboard.writeText(t);static async ReadImage(){const t=await navigator.clipboard.read();for(const e of t)for(const t of["image/png","image/jpeg","image/gif","image/webp"])if(e.types.includes(t))return await e.getType(t);return null}static WriteImage=async t=>{const e=new ClipboardItem({[t.type]:t});return navigator.clipboard.write([e])};static WriteMultiple=async(t,e)=>{const a=new Blob([t],{type:"text/plain"}),i=new ClipboardItem({"text/plain":a,[e.type]:e});return navigator.clipboard.write([i])}}window.GizmoWebJSInterop=window.GizmoWebJSInterop||{},window.GizmoWebJSInterop.Clipboard=Clipboard;